-- BankJobz: full sourced-listing rebuild, 2026-11-03. Paste into the Neon SQL Editor and Run. Safe to re-run.
-- Policy change: sourced listings may only link to the institution's own careers/ATS page.
-- Step 1 closes EVERY open sourced listing (paid Direct postings are untouched).
-- Step 2 inserts the new set: every link was fetched and showed the job open on the employer's site.

UPDATE jobs SET status = 'closed', updated_at = now() WHERE employer_id IS NULL AND status = 'open';

ON CONFLICT (source_url) DO UPDATE SET status = 'open', title = EXCLUDED.title, summary = EXCLUDED.summary,
  salary_min = EXCLUDED.salary_min, salary_max = EXCLUDED.salary_max, last_checked_at = now(),
  updated_at = now(), expires_at = now() + interval '30 days';

-- Check: open sourced listings per department (expect 6-7 in each of the 10)
SELECT category, COUNT(*) FROM jobs WHERE employer_id IS NULL AND status = 'open' GROUP BY category ORDER BY category;
